export async function getQuestions(
  subject: Subject,
  difficulty: Difficulty,
  count: number = 10,
  language: Language = 'en'
): Promise<Question[]> {
  const pool = questionBank.filter(q => q.subject === subject && q.difficulty === difficulty);
  const selected = await pickQuestions(pool, count, subject, difficulty);

  if (language === 'en') return selected;

  return selected.map(q => {
    const trans = q.translations?.[language];
    if (trans) return { ...q, question: trans.question, options: trans.options };
    return q;
  });
}

export function getDifficultyInfo(difficulty: Difficulty) {
  return difficulties.find(d => d.id === difficulty)!;
}

export function getSubjectInfo(subject: Subject) {
  return subjects.find(s => s.id === subject)!;
}
